use crate::aap::caps::inference_llm;

struct Node;

const MAX_QUESTION: usize = 512;

/// Truncate to at most `max` chars on a char boundary (bytes stay valid UTF-8).
fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

/// Map a free-text model label to the closed intent set. Anything we do not
/// recognise collapses to `Unknown`; the enum has no "other" case, so hostile
/// text cannot widen the set regardless of what the model emits.
fn parse_intent(raw: &str) -> Intent {
    let norm: String = raw
        .trim()
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c == '-' || c == ' ' { '_' } else { c })
        .collect();

    match norm.as_str() {
        s if s.contains("billing") => Intent::BillingQuestion,
        s if s.contains("technical") || s.contains("support") => Intent::TechnicalSupport,
        s if s.contains("account") => Intent::AccountChange,
        s if s.contains("general") || s.contains("inquiry") => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Precondition (len(value.text) <= 4000) is a graph-level guarantee on
        // the input; we treat the text as the untrusted material it is.
        let text = message.text;

        // One inference call — the whole of this node's authority. The model
        // is asked to label the message; its answer only influences, it cannot
        // act (no tool interface is in scope).
        let system = "You classify a customer support message. Reply with exactly \
                      one of these labels and nothing else: billing_question, \
                      technical_support, account_change, general_inquiry, unknown.";
        let label = inference_llm::infer(system, &text, "classify");

        let intent = parse_intent(&label);

        // The question is the bounded free-text residual. Enforce the output
        // contract here rather than trusting any upstream length: len <= 512.
        let question = truncate_chars(text.trim(), MAX_QUESTION);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

